create table if not exists agentes (is_deleted boolean not null, id bigint generated by default as identity, especialidade varchar(255) not null check ((especialidade in ('INVESTIGACAO','CONTENCAO_FISICA','ANALISE_HISTORICA','ENGENHARIA_TEMPORAL'))), nome varchar(255) not null, situacao varchar(255) not null check ((situacao in ('DISPONÍVEL','EM_MISSÃO','SUSPENSO','INATIVO'))), primary key (id));
create table if not exists anomalias (is_active boolean not null, is_deleted boolean not null, data_deteccao timestamp(6) not null, evento_id bigint, id bigint generated by default as identity, divergencia varchar(255) not null, estado varchar(255) not null check ((estado in ('DETECTADA','EM_ANÁLISE','CONFIRMADA','EM_CORREÇÃO','ESTABILIZADA','IRREVERSÍVEL'))), nome varchar(255) not null, observacoes varchar(255) not null, origem varchar(255), risco varchar(255) not null check ((risco in ('BAIXO','MODERADO','ALTO','CRÍTICO'))), primary key (id));
create table if not exists autorizacoes_operacao (id bigint generated by default as identity, instante timestamp(6) not null, missao_id bigint not null unique, responsavel_id bigint not null, observacao varchar(255) not null, primary key (id));
create table if not exists encerramento_missoes (id bigint generated by default as identity, missao_id bigint not null unique, impacto varchar(255) not null check ((impacto in ('MÍNIMO','CONTROLADO','SIGNIFICATIVO','SEVERO'))), observacoes_relevantes varchar(255) not null, resultado varchar(255) not null check ((resultado in ('SUCESSO','SUCESSO_PARCIAL','FALHA'))), resumo varchar(255) not null, situacao_anomalia varchar(255) not null check ((situacao_anomalia in ('DETECTADA','EM_ANÁLISE','CONFIRMADA','EM_CORREÇÃO','ESTABILIZADA','IRREVERSÍVEL'))), primary key (id));
create table if not exists eventos_historicos (data_fim date not null, data_inicio date not null, is_deleted boolean not null, id bigint generated by default as identity, descricao varchar(255) not null, importancia varchar(255) not null check ((importancia in ('BAIXA','MODERADA','ALTA','CRÍTICA'))), nome varchar(255) not null, primary key (id));
create table if not exists intervencoes (agente_id bigint not null, data timestamp(6) not null, id bigint generated by default as identity, missao_id bigint not null, acao_executada varchar(255) not null, impacto_estimado varchar(255) not null check ((impacto_estimado in ('MÍNIMO','CONTROLADO','SIGNIFICATIVO','SEVERO'))), justificativa varchar(255) not null, resultado_observado varchar(255) not null, primary key (id));
create table if not exists missoes (data_fim date, data_inicio date not null, is_deleted boolean not null, anomalia_id bigint not null, id bigint generated by default as identity, destino_temporal varchar(255) not null, estado varchar(255) not null check ((estado in ('PLANEJADA','AUTORIZADA','EM_EXECUÇÃO','CONCLUÍDA','CANCELADA','FALHOU'))), objetivo varchar(255) not null, prioridade varchar(255) not null check ((prioridade in ('BAIXA','NORMAL','ALTA','EMERGÊNCIA'))), primary key (id));
create table if not exists missoes_agentes (agentes_id bigint not null, missao_id bigint not null, primary key (agentes_id, missao_id));
create table if not exists usuarios (id bigint generated by default as identity, login varchar(255) not null, role varchar(255) not null check ((role in ('OPERADOR','AGENTE','SUPERVISOR','ADMINISTRADOR'))), senha varchar(255) not null, primary key (id));
alter table if exists anomalias add constraint FKdwlvvay0hqk2efnr7o4smw6j1 foreign key (evento_id) references eventos_historicos;
